#include <stdio.h>

int factorial(int n) {
    int result = 1;
    for (int i = 1; i <= n; i++) {
        result *= i;
    }
    return result;
}

int isPrime(int num) {
    if (num < 2) return 0;
    for (int i = 2; i * i <= num; i++) {
        if (num % i == 0) return 0;
    }
    return 1;
}

void printFibonacci(int count) {
    int a = 0, b = 1;
    printf("Fibonacci: ");
    for (int i = 0; i < count; i++) {
        printf("%d ", a);
        int next = a + b;
        a = b;
        b = next;
    }
    printf("\n");
}

int main() {
    printf("=== Factorial Table ===\n");
    for (int n = 1; n <= 5; n++) {
        printf("%d! = %d\n", n, factorial(n));
    }

    printf("\n=== Prime Numbers up to 20 ===\n");
    for (int x = 2; x <= 20; x++) {
        if (isPrime(x)) {
            printf("%d ", x)
        }
    }
    printf("\n");

    printf("\n");
    printFibonacci(10);

    printf("\nProgram finished successfully.\n");
    return 0;
}

